  ('a1-series', 'A1', false, 9, '{"id":"a1-series","group":"A1","topics":["A1-QUANT-SERIES"],"icon":"🔢","title":"อนุกรม","hub":"อนุกรม","hubSub":"หาผลต่างก่อนเสมอ","intro":"เจอโจทย์อนุกรม ให้ลองตามลำดับกิ่ง 1 → 6","branches":[{"id":"add","icon":"➕","tone":"pink","title":"1. ผลต่างคงที่","big":"+ เท่ากัน","must":true,"ask":"ขั้นแรกของอนุกรมทุกข้อ คือหาอะไร","sub":"ลบตัวหน้าออกจากตัวหลัง ถ้าเท่ากันทุกคู่ จบ","blocks":[{"k":"seq","terms":["2","5","8","11","14","17"],"rows":[{"ops":["+3","+3","+3","+3","+3"]}],"ans":5,"cap":"บวกเพิ่มขึ้นคงที่ทีละ 3 → ตอบ 17"},{"k":"seq","terms":["50","44","38","32","26"],"rows":[{"ops":["−6","−6","−6","−6"]}],"ans":4,"cap":"ลดลงคงที่ทีละ 6 → ตอบ 26"},{"k":"example","q":"3, 7, 11, 15, ?","steps":["ผลต่าง 4, 4, 4","15 + 4 = 19"],"a":"19"},{"k":"memo","t":"เขียนผลต่างไว้ใต้ตัวเลขทุกครั้ง แค่นี้ก็ตอบได้ครึ่งหนึ่งของข้อสอบ"}]},{"id":"mul","icon":"✖️","tone":"mint","title":"2. คูณหรือหารเท่ากัน","big":"× เท่ากัน","ask":"ผลต่างโตเร็วมาก ให้ลองอะไร","sub":"ตัวเลขโตเร็วมาก ลองหารตัวหลังด้วยตัวหน้า","blocks":[{"k":"seq","terms":["2","6","18","54","162"],"rows":[{"ops":["×3","×3","×3","×3"]}],"ans":4,"cap":"คูณ 3 ทุกตัว → ตอบ 162"},{"k":"seq","terms":["3","7","15","31","63"],"rows":[{"ops":["×2+1","×2+1","×2+1","×2+1"]}],"ans":4,"cap":"คูณ 2 แล้วบวก 1 → ตอบ 63"},{"k":"example","q":"2, 6, 18, 54, ?","steps":["6÷2 = 3, 18÷6 = 3, 54÷18 = 3","54 × 3 = 162"],"a":"162"},{"k":"note","t":"บางข้อเป็น ×2 +1, ×2 +2 ... ถ้าคูณไม่ลงตัวพอดี ลองคูณแล้วบวกต่อ"}]},{"id":"diff2","icon":"🪜","tone":"sky","title":"3. ผลต่าง 2 ชั้น","big":"ต่างของต่าง","hot":true,"ask":"ผลต่างชั้นแรกไม่เท่ากัน ทำอย่างไรต่อ","sub":"ผลต่างชั้นแรกไม่เท่า ให้หาผลต่างของผลต่างอีกที","blocks":[{"k":"seq","terms":["2","5","10","17","26","37"],"rows":[{"ops":["+3","+5","+7","+9","+11"]},{"ops":["+2","+2","+2","+2"],"level2":true}],"ans":5,"cap":"ชั้นแรก +3 +5 +7 +9 · ชั้นสองเพิ่มทีละ 2 → ถัดไป +11 → ตอบ 37"},{"k":"example","q":"2, 5, 10, 17, 26, ?","steps":["ผลต่างชั้นแรก 3, 5, 7, 9","ผลต่างชั